import {
  type ReactNode,
  useState,
  useEffect,
  useCallback,
  useRef,
  createContext,
  useContext,
} from 'react';
import { IconButton } from '../atoms/IconButton';

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

// Debe coincidir con la animacion de salida de dialog__content--exiting en el CSS.
const EXIT_DURATION_MS = 200;

const FOCUSABLE = [
  'a[href]',
  'button:not([disabled])',
  'input:not([disabled])',
  'select:not([disabled])',
  'textarea:not([disabled])',
  '[tabindex]:not([tabindex="-1"])',
].join(',');

const CloseIcon = () => (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <line x1="18" y1="6" x2="6" y2="18" />
    <line x1="6" y1="6" x2="18" y2="18" />
  </svg>
);

/* ---- Context ---- */

type DialogContextValue = {
  open: boolean;
  setOpen: (v: boolean) => void;
};

const DialogContext = createContext<DialogContextValue | null>(null);

function useDialog() {
  const ctx = useContext(DialogContext);
  if (!ctx) throw new Error('Dialog components must be used within <Dialog>');
  return ctx;
}

/* ---- Root ---- */

export type DialogProps = {
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  children: ReactNode;
};

export function Dialog({ open: controlledOpen, onOpenChange, children }: DialogProps) {
  const [internalOpen, setInternalOpen] = useState(false);
  const open = controlledOpen ?? internalOpen;

  const setOpen = useCallback(
    (v: boolean) => {
      onOpenChange ? onOpenChange(v) : setInternalOpen(v);
    },
    [onOpenChange],
  );

  return (
    <DialogContext.Provider value={{ open, setOpen }}>
      {children}
    </DialogContext.Provider>
  );
}

/* ---- Trigger ---- */

export function DialogTrigger({ children, className }: { children: ReactNode; className?: string }) {
  const { setOpen } = useDialog();
  return (
    <div
      role="button"
      tabIndex={0}
      className={className}
      style={{ display: 'inline-flex' }}
      onClick={() => setOpen(true)}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setOpen(true); }
      }}
    >
      {children}
    </div>
  );
}

/* ---- Content ---- */

export type DialogContentProps = {
  showCloseButton?: boolean;
  children: ReactNode;
  className?: string;
};

export function DialogContent({ showCloseButton = true, children, className }: DialogContentProps) {
  const { open, setOpen } = useDialog();
  const [exiting, setExiting] = useState(false);
  const [mounted, setMounted] = useState(false);
  const contentRef = useRef<HTMLDivElement>(null);

  // `open` es lo unico que decide si el dialogo esta abierto. Si el consumidor lo
  // controla y veta el cierre, el contenido tiene que quedarse: desmontar desde
  // aqui lo dejaba cerrado para siempre, porque `open` ya nunca vuelve a cambiar.
  // `mounted` solo estira la vida en el DOM lo que dura la animacion de salida.
  useEffect(() => {
    if (open) {
      setMounted(true);
      setExiting(false);
      return;
    }
    if (!mounted) return;
    setExiting(true);
    const timer = setTimeout(() => {
      setMounted(false);
      setExiting(false);
    }, EXIT_DURATION_MS);
    return () => clearTimeout(timer);
  }, [open, mounted]);

  const handleClose = useCallback(() => {
    setOpen(false);
  }, [setOpen]);

  // Escape key
  useEffect(() => {
    if (!mounted) return;
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') handleClose();
    };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [mounted, handleClose]);

  // Scroll lock
  useEffect(() => {
    if (!mounted) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = prev; };
  }, [mounted]);

  // Al abrir, el foco entra al dialogo; al cerrar vuelve a quien lo abrio, que es
  // donde estaba el usuario antes de la interrupcion. Sin esta vuelta, el foco cae
  // al principio del documento y quien navega con teclado pierde el sitio.
  useEffect(() => {
    if (!mounted) return;
    const opener = document.activeElement as HTMLElement | null;
    contentRef.current?.focus();
    return () => {
      if (opener && document.contains(opener)) opener.focus();
    };
  }, [mounted]);

  // Focus trap real: con aria-modal el lector de pantalla ya ignora el fondo, pero
  // el Tab del navegador no, y sin esto el foco se escapa a la pagina de atras.
  useEffect(() => {
    if (!mounted) return;
    const node = contentRef.current;
    if (!node) return;

    const handler = (e: KeyboardEvent) => {
      if (e.key !== 'Tab') return;
      const focusables = Array.from(node.querySelectorAll<HTMLElement>(FOCUSABLE));
      if (focusables.length === 0) {
        e.preventDefault();
        node.focus();
        return;
      }
      const first = focusables[0];
      const last = focusables[focusables.length - 1];
      const active = document.activeElement;
      const outside = !node.contains(active);

      if (e.shiftKey && (active === first || active === node || outside)) {
        e.preventDefault();
        last.focus();
      } else if (!e.shiftKey && (active === last || outside)) {
        e.preventDefault();
        first.focus();
      }
    };

    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [mounted]);

  if (!mounted) return null;

  return (
    <>
      <div
        className={cn('dialog__overlay', exiting && 'dialog__overlay--exiting')}
        onClick={handleClose}
        aria-hidden="true"
      />
      <div
        ref={contentRef}
        role="dialog"
        aria-modal="true"
        tabIndex={-1}
        className={cn('dialog__content', exiting && 'dialog__content--exiting', className)}
      >
        {children}
        {showCloseButton && (
          <IconButton
            variant="tertiary"
            size="xs"
            className="dialog__close"
            icon={<CloseIcon />}
            aria-label="Close"
            onClick={handleClose}
          />
        )}
      </div>
    </>
  );
}

/* ---- Header ---- */

export function DialogHeader({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={cn('dialog__header', className)}>{children}</div>;
}

/* ---- Title ---- */

export function DialogTitle({ children, className }: { children: ReactNode; className?: string }) {
  return <h2 className={cn('dialog__title', className)}>{children}</h2>;
}

/* ---- Description ---- */

export function DialogDescription({ children, className }: { children: ReactNode; className?: string }) {
  return <p className={cn('dialog__description', className)}>{children}</p>;
}

/* ---- Body ---- */

export function DialogBody({ children, className }: { children: ReactNode; className?: string }) {
  return <div className={cn('dialog__body', className)}>{children}</div>;
}

/* ---- Footer ---- */

export type DialogFooterProps = {
  sticky?: boolean;
  children: ReactNode;
  className?: string;
};

export function DialogFooter({ sticky = false, children, className }: DialogFooterProps) {
  return (
    <div className={cn('dialog__footer', sticky && 'dialog__footer--sticky', className)}>
      {children}
    </div>
  );
}

/* -------------------------------------------------------------------------
   Dialog

   Modal window with overlay. Focus-trapped, scroll-locked.
   Composable: Dialog > Trigger + Content > Header + Footer

   Parts: .dialog__overlay, .dialog__content, .dialog__header,
          .dialog__title, .dialog__description, .dialog__footer,
          .dialog__close
   ------------------------------------------------------------------------- */

/* ---- Overlay ---- */

.dialog__overlay {
  position: fixed;
  inset: 0;
  z-index: var(--z-index-40);
  background-color: var(--overlay);
  animation: dialog-overlay-in var(--duration-200) var(--easing-out);
}

.dialog__overlay--exiting {
  animation: dialog-overlay-out var(--duration-200) var(--easing-in) forwards;
}

@keyframes dialog-overlay-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes dialog-overlay-out {
  from { opacity: 1; }
  to { opacity: 0; }
}

/* ---- Content ---- */

.dialog__content {
  position: fixed;
  z-index: var(--z-index-50);
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: calc(100% - var(--spacing-8, 32px));
  max-width: 512px;
  max-height: calc(100vh - var(--spacing-8, 32px));
  display: flex;
  flex-direction: column;
  border: var(--stroke-hairline) solid var(--border);
  border-radius: var(--radius-xl);
  background-color: var(--popover);
  color: var(--popover-foreground);
  box-shadow: var(--shadow-xl);
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  animation: dialog-content-in var(--duration-300) var(--easing-out);
}

.dialog__content--exiting {
  animation: dialog-content-out var(--duration-200) var(--easing-in) forwards;
}

@keyframes dialog-content-in {
  from {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.95);
  }
  to {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
}

@keyframes dialog-content-out {
  from {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
  to {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.95);
  }
}

/* ---- Header ---- */

.dialog__header {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-2, 8px);
  padding: var(--spacing-6, 24px);
  padding-bottom: 0;
}

/* ---- Title ---- */

.dialog__title {
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-semibold);
  line-height: var(--line-height-lg);
  color: var(--foreground);
  margin: 0;
}

/* ---- Description ---- */

.dialog__description {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-sm);
  color: var(--muted-foreground);
  margin: 0;
}

/* ---- Body (scrollable) ---- */

.dialog__body {
  flex: 1;
  overflow-y: auto;
  padding: var(--spacing-6, 24px);
}

/* ---- Footer ---- */

.dialog__footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: var(--spacing-3, 12px);
  padding: var(--spacing-6, 24px);
  padding-top: 0;
}

.dialog__footer--sticky {
  border-top: var(--stroke-hairline) solid var(--border);
  padding-top: var(--spacing-6, 24px);
}

/* ---- Close button ---- */

.dialog__close {
  position: absolute;
  top: var(--spacing-4, 16px);
  right: var(--spacing-4, 16px);
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .dialog__overlay,
  .dialog__overlay--exiting,
  .dialog__content,
  .dialog__content--exiting {
    animation-duration: 0ms;
  }
}

